-- Private settings for QueryHub. DO NOT edit this file in place.
--
--   1. Copy it to setup/secrets.sql (that name is in .gitignore, so it
--      will never be committed).
--   2. Fill in the two values below in the copy.
--   3. Run the copy in the Supabase SQL editor, after schema.sql.
--
-- Re-run it any time to rotate the invite code or change admins.
-- The code is stored only as a bcrypt hash; the plaintext exists only here.

-- The invite code people must enter to sign up. Make it long and random.
update public.app_config set value = extensions.crypt('PUT-INVITE-CODE-HERE', extensions.gen_salt('bf'))
where key = 'invite_code_hash';
insert into public.app_config (key, value)
select 'invite_code_hash', extensions.crypt('PUT-INVITE-CODE-HERE', extensions.gen_salt('bf'))
where not exists (select 1 from public.app_config where key = 'invite_code_hash');

-- Your own account (the one created from the Supabase dashboard) becomes admin,
-- and any queries that predate ownership are assigned to it.
update public.profiles
set is_admin = true
where id in (select id from auth.users where email = 'PUT-ADMIN-EMAIL-HERE');

update public.queries
set owner_id = (select id from auth.users where email = 'PUT-ADMIN-EMAIL-HERE')
where owner_id is null;
